const body = $input.first().json;
const alerts = body.alerts || [];
const alert = alerts[0] || {};
const desc = (alert.annotations && (alert.annotations.description || alert.annotations.__value_string__) || '');

function parseFields(line) {
  var fields = {};
  var regex = /(\w+)=([^\s]+)/g;
  var m;
  while ((m = regex.exec(line)) !== null) {
    fields[m[1]] = m[2];
  }
  return fields;
}

var fields = parseFields(desc);

return [{
  json: {
    type: fields.type || 'UNKNOWN',
    auctionId: fields.auctionId || '',
    cardId: fields.cardId || '',
    sellerId: fields.sellerId || '',
    winnerId: fields.winnerId || fields.buyerId || '',
    finalPrice: Number(fields.finalPrice) || 0,
    marketPrice: Number(fields.marketPrice) || 0,
    ratio: fields.ratio || '0',
    alertTime: alert.startsAt || new Date().toISOString(),
    generatorURL: alert.generatorURL || '',
    rawLog: desc,
    geminiRequest: {
      model: 'gemini-2.0-flash',
      max_tokens: 250,
      messages: [
        {
          role: 'system',
          content: 'POCAT 카드 거래 이상 감지 AI입니다. 거래 정보를 분석하고 한국어로 3줄 이내 답변하세요.'
        },
        {
          role: 'user',
          content: '이상 경매 거래 감지\n타입: ' + (fields.type || '') + '\n경매ID: ' + (fields.auctionId || '') + '\n카드ID: ' + (fields.cardId || '') + '\n판매자: ' + (fields.sellerId || '') + '\n낙찰자: ' + (fields.winnerId || fields.buyerId || '') + '\n최종가: ' + (fields.finalPrice || '') + '원\n시장 평균가: ' + (fields.marketPrice || '') + '원\n비율: ' + (fields.ratio || '') + '배 (기준 3.0배)\n\n유형 분류(가격조작/희귀카드정상거래/봇의심/일시적시장변동)와 필요 조치를 답변하세요.'
        }
      ]
    }
  }
}];

const geminiResp = $json;
const analysis = (geminiResp.choices && geminiResp.choices[0] && geminiResp.choices[0].message && geminiResp.choices[0].message.content) || '분석 실패';
const prev = $('Parse AUCTION_ANOMALY Log').first().json;
const ratio = parseFloat(prev.ratio) || 0;
const color = ratio > 5 ? 'danger' : 'warning';
const emoji = ratio > 5 ? '🚨' : '⚠️';

return [{
  json: {
    slackPayload: {
      text: emoji + ' *[AUCTION_ANOMALY] 이상 경매 거래 감지*',
      attachments: [{
        color: color,
        fields: [
          { title: '타입', value: prev.type || '-', short: true },
          { title: '경매 ID', value: prev.auctionId || '-', short: true },
          { title: '카드 ID', value: prev.cardId || '-', short: true },
          { title: '비율', value: prev.ratio + '배', short: true },
          { title: '최종가', value: (prev.finalPrice || 0).toLocaleString() + '원', short: true },
          { title: '시장 평균가', value: (prev.marketPrice || 0).toLocaleString() + '원', short: true },
          { title: '판매자 ID', value: prev.sellerId || '-', short: true },
          { title: '낙찰자 ID', value: prev.winnerId || '-', short: true },
          { title: 'AI 분석', value: analysis, short: false }
        ],
        footer: 'POCAT Monitoring | ' + prev.alertTime
      }]
    }
  }
}];
